import cv2, glob, numpy as np

frames=sorted(glob.glob('/root/keyframes_*.png'))

def load_gray(p):
    img=cv2.imread(p, cv2.IMREAD_GRAYSCALE)
    if img is None:
        raise SystemExit(f'failed {p}')
    return img

templates={name: load_gray(f'/root/{name}.png') for name in ['coin','enemy','turtle']}


def count_matches(frame, template, thresh):
    res=cv2.matchTemplate(frame, template, cv2.TM_CCOEFF_NORMED)
    loc=np.where(res>=thresh)
    h, w = template.shape
    boxes=[]
    scores=[]
    for (y,x) in zip(*loc):
        boxes.append([int(x), int(y), int(w), int(h)])
        scores.append(float(res[y,x]))
    if not boxes:
        return 0
    idxs=cv2.dnn.NMSBoxes(boxes, scores, thresh, 0.3)
    if len(idxs)==0:
        return 0
    return len(idxs)

thresholds={'coin':0.8,'enemy':0.8,'turtle':0.8}

for f in frames:
    frame=load_gray(f)
    counts={name: count_matches(frame, tmpl, thresholds[name]) for name, tmpl in templates.items()}
    print(f, counts)
